public enum EngineEvent {
    
    case checkRequested(phrase: String, deadlineMs: UInt64
    )
    case headsUp(summary: String
    )
    case unlockLocation(summary: String
    )
    case snatchDetected(summary: String
    )
    case resolved
    case riskBandChanged(band: UInt8
    )
    case batteryDying
    case locationIntervalChanged(seconds: UInt32
    )
    case samplingRateChanged(hz: UInt32, gyro: Bool
    )
    case signalIncident(record: IncidentRecord
    )
    case callOptionAvailable(summary: String
    )
}


#if compiler(>=6)
extension EngineEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEngineEvent: FfiConverterRustBuffer {
    typealias SwiftType = EngineEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EngineEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .checkRequested(phrase: try FfiConverterString.read(from: &buf), deadlineMs: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .headsUp(summary: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .unlockLocation(summary: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .snatchDetected(summary: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .resolved
        
        case 6: return .riskBandChanged(band: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 7: return .batteryDying
        
        case 8: return .locationIntervalChanged(seconds: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 9: return .samplingRateChanged(hz: try FfiConverterUInt32.read(from: &buf), gyro: try FfiConverterBool.read(from: &buf)
        )
        
        case 10: return .signalIncident(record: try FfiConverterTypeIncidentRecord.read(from: &buf)
        )
        
        case 11: return .callOptionAvailable(summary: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EngineEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .checkRequested(phrase,deadlineMs):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(phrase, into: &buf)
            FfiConverterUInt64.write(deadlineMs, into: &buf)
            
        
        case let .headsUp(summary):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(summary, into: &buf)
            
        
        case let .unlockLocation(summary):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(summary, into: &buf)
            
        
        case let .snatchDetected(summary):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(summary, into: &buf)
            
        
        case .resolved:
            writeInt(&buf, Int32(5))
        
        
        case let .riskBandChanged(band):
            writeInt(&buf, Int32(6))
            FfiConverterUInt8.write(band, into: &buf)
            
        
        case .batteryDying:
            writeInt(&buf, Int32(7))
        
        
        case let .locationIntervalChanged(seconds):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(seconds, into: &buf)
            
        
        case let .samplingRateChanged(hz,gyro):
            writeInt(&buf, Int32(9))
            FfiConverterUInt32.write(hz, into: &buf)
            FfiConverterBool.write(gyro, into: &buf)
            
        
        case let .signalIncident(record):
            writeInt(&buf, Int32(10))
            FfiConverterTypeIncidentRecord.write(record, into: &buf)
            
        
        case let .callOptionAvailable(summary):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(summary, into: &buf)
            
        }
    }
}


